package org.eclipse.rdf4j.tools.serverboot;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.catchThrowable;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mockConstruction;

import java.util.concurrent.atomic.AtomicBoolean;

import org.junit.jupiter.api.Test;
import org.mockito.MockedConstruction;
import org.slf4j.LoggerFactory;

import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.AppenderBase;

class ShutdownCoordinatorTest {

	@Test
	void diagnosticLoggerFailureDoesNotReplaceFatalStartupFailure() {
		OutOfMemoryError startupFailure = new OutOfMemoryError("simulated graceful-thread startup failure");
		IllegalStateException emergencyFailure = new IllegalStateException("simulated emergency halt failure");
		IllegalStateException exitFailure = new IllegalStateException("simulated exit failure");
		AtomicBoolean logAttempted = new AtomicBoolean();
		Logger coordinatorLogger = (Logger) LoggerFactory.getLogger(ShutdownCoordinator.class);
		AppenderBase<ILoggingEvent> failingAppender = new AppenderBase<>() {
			@Override
			protected void append(ILoggingEvent event) {
				if (event.getFormattedMessage().contains("Unable to start emergency shutdown")) {
					logAttempted.set(true);
					throw new OutOfMemoryError("simulated diagnostic logger exhaustion");
				}
			}
		};
		failingAppender.setContext(coordinatorLogger.getLoggerContext());
		failingAppender.start();
		coordinatorLogger.addAppender(failingAppender);
		try (MockedConstruction<Thread> ignored = mockConstruction(Thread.class,
				(thread, context) -> doThrow(startupFailure).when(thread).start())) {
			ShutdownCoordinator coordinator = new ShutdownCoordinator(null, status -> {
				throw exitFailure;
			}, status -> {
				throw emergencyFailure;
			}, false);
			try {
				Throwable thrown = catchThrowable(() -> coordinator.requestOutOfMemory("OutOfMemoryError"));

				assertThat(thrown).as("diagnostic logging must preserve the startup failure")
						.isSameAs(startupFailure);
				assertThat(logAttempted).as("the startup diagnostic must be attempted").isTrue();
			} finally {
				coordinator.close();
			}
		} finally {
			coordinatorLogger.detachAppender(failingAppender);
			failingAppender.stop();
		}
	}
}
